	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		InventoryTransaction
	 */
		public InventoryTransaction createInventoryTransaction( CreateInventoryTransactionCommand command ) {

		InventoryTransaction entity = new InventoryTransaction();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setInventoryTransactionId( command.getInventoryTransactionId() );
            entity.setTransactionNumber( command.getTransactionNumber() );
            entity.setQuantity( command.getQuantity() );
            entity.setUnitCost( command.getUnitCost() );
            entity.setTransactionDate( command.getTransactionDate() );
            entity.setReasonCode( command.getReasonCode() );
            entity.setTransactionType( command.getTransactionType() );
            entity.setUnitOfMeasure( command.getUnitOfMeasure() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of InventoryTransaction {0} ", entity.toString() );

		return entity;
	}

